const input = $('Tool Trigger: Cancelar Cita').first().json;
const items = $input.all();
const targetWa = (input.wa_id || '').toString().replace(/\D/g, '');

function parseSheetDate(str) {
  if (!str) return null;
  str = str.toString().trim();
  if (/^\d{4}-\d{2}-\d{2}/.test(str)) {
    const d = new Date(str);
    return isNaN(d.getTime()) ? null : d;
  }
  const match = str.match(/(\d{1,2})\/(\d{1,2})\/(\d{4})[,\s]+(\d{1,2}):(\d{2})(?::(\d{2}))?\s*(am|pm|a\.?\s*m\.?|p\.?\s*m\.?)?/i);
  if (match) {
    let [_, d, m, y, hh, mm, ss, mer] = match;
    let h = parseInt(hh);
    if (mer) {
      const cleanMer = mer.toLowerCase().replace(/[\.\s]/g, '');
      if (cleanMer === 'pm' && h < 12) h += 12;
      if (cleanMer === 'am' && h === 12) h = 0;
    }
    const isoStr = y + '-' + m.padStart(2, '0') + '-' + d.padStart(2, '0') + 'T' + String(h).padStart(2, '0') + ':' + mm + ':00-05:00';
    const dObj = new Date(isoStr);
    if (!isNaN(dObj.getTime())) return dObj;
  }
  const fallback = new Date(str);
  return isNaN(fallback.getTime()) ? null : fallback;
}

// 1. Buscar de abajo hacia arriba la cita confirmada del cliente
let citaEncontrada = null;
for (let i = items.length - 1; i >= 0; i--) {
  const row = items[i].json;
  if (!row) continue;
  const rowWa = (row['WhatsApp'] || '').toString().replace(/\D/g, '');
  const estado = (row['Estado'] || 'confirmada').toString().trim().toLowerCase();

  const waMatch = (rowWa === targetWa || (rowWa.length >= 10 && targetWa.length >= 10 && rowWa.slice(-10) === targetWa.slice(-10)));
  if (waMatch && estado === 'confirmada') {
    citaEncontrada = row;
    break;
  }
}

// 2. Si no encontró por WhatsApp exacto, tomar la cita confirmada más reciente
if (!citaEncontrada) {
  for (let i = items.length - 1; i >= 0; i--) {
    const row = items[i].json;
    if (!row) continue;
    const estado = (row['Estado'] || 'confirmada').toString().trim().toLowerCase();
    if (estado === 'confirmada') {
      citaEncontrada = row;
      break;
    }
  }
}

if (!citaEncontrada) {
  return [{
    json: {
      puede_cancelar: false,
      motivo: 'no_encontrada',
      mensaje: 'No encontré ninguna cita activa confirmada en nuestra agenda para cancelar. Si crees que se trata de un error, con gusto le aviso a Andrés.'
    }
  }];
}

const rawFecha = citaEncontrada['Fecha Cita'] || '';
const fechaCita = parseSheetDate(rawFecha);
const ahora = new Date();
const fechaRegistro = (citaEncontrada['Fecha Registro'] || '').toString().trim();

if (!fechaCita) {
  return [{
    json: {
      puede_cancelar: true,
      fecha_registro: fechaRegistro,
      cliente: citaEncontrada['Nombre Cliente'] || 'Cliente',
      wa_id: (citaEncontrada['WhatsApp'] || targetWa).toString().trim(),
      servicio: citaEncontrada['Servicio'] || 'Servicio',
      fecha_cita: rawFecha.toString().trim(),
      precio: citaEncontrada['Precio COP'] || 45000
    }
  }];
}

const diffHoras = (fechaCita - ahora) / (1000 * 60 * 60);

// Regla de negocio: mínimo 2 horas de anticipación
if (diffHoras >= 0 && diffHoras < 2) {
  return [{
    json: {
      puede_cancelar: false,
      motivo: 'menos_de_2_horas',
      horas_restantes: diffHoras.toFixed(1),
      mensaje: 'Por políticas de Andrés Peluquería, las cancelaciones automáticas deben realizarse con un mínimo de 2 horas de anticipación. Como faltan menos de 2 horas para tu cita, por favor comunícate directamente con Andrés para revisar tu caso.'
    }
  }];
}

return [{
  json: {
    puede_cancelar: true,
    fecha_registro: fechaRegistro,
    cliente: citaEncontrada['Nombre Cliente'] || 'Cliente',
    wa_id: (citaEncontrada['WhatsApp'] || targetWa).toString().trim(),
    servicio: citaEncontrada['Servicio'] || 'Servicio',
    fecha_cita: rawFecha.toString().trim(),
    precio: citaEncontrada['Precio COP'] || 45000
  }
}];

