UPDATE citas
SET estado = 'cancelada', actualizada_en = CURRENT_TIMESTAMP
WHERE cliente_id IN (
  SELECT id FROM clientes WHERE regexp_replace(wa_id, '\D', '', 'g') = regexp_replace($1, '\D', '', 'g')
)
AND estado ILIKE 'confirmada';

